import { useEffect } from 'react';
import { load } from '@2gis/mapgl';
import { useMapglContext } from './MapglContext';
import { Clusterer } from '@2gis/mapgl-clusterer';
import { RulerControl } from '@2gis/mapgl-ruler';
import { Directions } from '@2gis/mapgl-directions';
import { useControlRotateClockwise } from './useControlRotateClockwise';
import { ControlRotateCounterclockwise } from './ControlRotateConterclockwise';
import { MapWrapper } from './MapWrapper';
import {FeatureCollection, Geometry, GeoJsonProperties} from 'geojson';
import geoData from './data/samarskaia-oblast.json';

export const MAP_CENTER = [50.100202, 53.195878];

export default function Mapgl() {
    const { setMapglContext } = useMapglContext();

    useEffect(() => {
        let map: mapgl.Map | undefined = undefined;
        let directions: Directions | undefined = undefined;
        let clusterer: Clusterer | undefined = undefined;

        
        load().then((mapgl) => {
            map = new mapgl.Map('map-container', {
                center: MAP_CENTER,
                zoom: 13,
                key: '3fbe9308-6c3e-460f-96fb-b5ed93f9188b',
                style:'490ee204-43a8-48f3-b132-99e42047ef1e',
                trafficControl: 'topRight',
                scaleControl: true
            });
            const data: FeatureCollection<Geometry, GeoJsonProperties> = geoData as FeatureCollection<Geometry, GeoJsonProperties>;
            const source = new mapgl.GeoJsonSource(map, {data, attributes: {visible:true}});
            const layer = {id: 'dtp-data-layer', filter: ['all', ['match', ['sourceAttr', 'visible'], [true], true, false,]], type: 'point' as const, style: {iconImage: 'police-JP', iconWidth: 15, iconPriority: 100, textField: ['get', 'weather'], textFont: 'TimesNewRoman', textColor: '#0098ea',},};
            map.on('styleload', () => {
                map?.addLayer(layer as any);
            })

            const layerTmprtr = {id: 'dtp-heatmap-layer', filter: ['match',['sourceAttr', 'visible'],[true],true,false,], type: 'heatmap' as const, style: {color: ['interpolate', ['linear'], ['heatmap-density'], 0, 'rgb(209, 161, 115)', 0.2, 'rgb(51, 146, 184)', 0.4, 'rgb(150, 89, 207)', 0.6, 'rgb(160, 50, 210)', 0.8, 'rgb(200, 20, 210)', 1, 'rgb(242, 2, 255)',], radius: 20, intensity: 0.8, opacity: 0.8, downscale: 1, },};
            
            map.on('styleload', () => {
                map?.addLayer(layerTmprtr as any);
            })

            map.on('click', (e) => console.log(e));
            

            /**
             * Ruler  plugin
             */

            const rulerControl = new RulerControl(map, { position: 'centerRight' });

            /**
             * Clusterer plugin
             */

            clusterer = new Clusterer(map, {
                radius: 60,
            });

            const markers = [
                { coordinates: [55.27887, 25.21001] },
                { coordinates: [55.30771, 25.20314] },
                { coordinates: [55.35266, 25.24382] },
            ];
            clusterer.load(markers);

            /**
             * Directions plugin
             */

            directions = new Directions(map, {
                directionsApiKey: 'rujany4131', // It's just demo key
            });

            directions.carRoute({
                points: [
                    [55.28273111108218, 25.234131928828333],
                    [55.35242563034581, 25.23925607042088],
                ],
            });

            setMapglContext({
                mapglInstance: map,
                rulerControl,
                mapgl,
            });
        });

        // Destroy the map, if Map component is going to be unmounted
        return () => {
            directions && directions.clear();
            clusterer && clusterer.destroy();
            map && map.destroy();
            setMapglContext({ mapglInstance: undefined, mapgl: undefined });
        };
    }, [setMapglContext]);

    useControlRotateClockwise();

    return (
        <>
            <MapWrapper />
            <ControlRotateCounterclockwise />
        </>
    );
}
