import { useCallback } from 'react';
import { useMapglContext } from './MapglContext';

function ButtonLightTheam(){
    const { mapglInstance } = useMapglContext();
    const onClick = useCallback(() => {
        if (!mapglInstance) {
            return;
        } 
        mapglInstance.setStyleById('c080bb6a-8134-4993-93a1-5b4d8c36a59b');
    }, [mapglInstance]);
    return (
        <button style={{ height: '24px' }} onClick={onClick}>
            Light
        </button>
    );
}
export default ButtonLightTheam;